#!/usr/bin/env python3
"""Gera corpus sintético, sem mídia de terceiros, para medir o BC5 original.

Requer mutagen somente para criar fixtures; os arquivos gerados vão no ZIP.
Não estabelece expectativas de resultado. Cada cenário testa uma hipótese.
"""
from __future__ import annotations
import base64
import hashlib
import json
import shutil
from pathlib import Path
from mutagen.id3 import ID3, TIT2, TPE1, TALB, TDRC, TYER, TXXX, COMM, APIC, delete as id3_delete
from mutagen.flac import FLAC, Picture
from mutagen.mp4 import MP4, MP4Cover, MP4FreeForm

ROOT=Path(__file__).resolve().parent
FILES=ROOT/'CASOS'
FILES.mkdir(exist_ok=True)
SOURCE=ROOT.parent/'RUST_APP'/'crates'/'bc5-media'/'tests'/'fixtures'
CASES=[]
# These are tiny audio waveforms generated by the earlier stage from synthetic signals.
PNG1=base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWP4z8DwHwAFgAI/ScL/nwAAAABJRU5ErkJggg==')
PNG2=base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVQIHWNgYGD4DwABBAEAHj4Z+AAAAABJRU5ErkJggg==')

def digest(p:Path):return hashlib.sha256(p.read_bytes()).hexdigest()
def copy_pair(id,ext):
    base=SOURCE/('A.'+ext)
    assert base.exists(),base
    a=FILES/(id+'_A.'+ext);b=FILES/(id+'_B.'+ext)
    shutil.copy2(base,a);shutil.copy2(base,b)
    return a,b

def mp3_clear(p):id3_delete(p)
def mp3_set(p,frames,version=4,only_v1=False):
    if only_v1: raise NotImplementedError
    mp3_clear(p)
    tag=ID3()
    for f in frames:tag.add(f)
    tag.save(p,v2_version=version,v1=0)

def id3v1(p,title,artist='BC5 test artist'):
    data=p.read_bytes()
    if len(data)>=128 and data[-128:-125]==b'TAG': data=data[:-128]
    fields=[title,artist,'BC5 test album','2026','original']
    sizes=[30,30,30,4,30]
    block=b'TAG'+b''.join(text.encode('latin1','replace')[:n].ljust(n,b'\x00') for text,n in zip(fields,sizes))+b'\x0d'
    assert len(block)==128
    p.write_bytes(data+block)

def v22(p,title):
    mp3_clear(p)
    content=b'\x00'+title.encode('latin1')
    frame=b'TT2'+len(content).to_bytes(3,'big')+content
    n=len(frame)
    syn=bytes([(n>>21)&127,(n>>14)&127,(n>>7)&127,n&127])
    p.write_bytes(b'ID3\x02\x00\x00'+syn+frame+p.read_bytes())

def flac_set(p,mapping):
    f=FLAC(p);f.clear()
    for k,v in mapping.items():f[k]=v
    f.save()

def mp4_set(p,mapping):
    m=MP4(p);m.clear()
    for k,v in mapping.items():m[k]=v
    m.save()

def add(id,ext,title,mutation,category):
    a,b=copy_pair(id,ext)
    mutation(a,b)
    assert a.exists() and b.exists()
    CASES.append({'id':id,'format':ext,'category':category,'investigation':title,
                  'left':a.name,'right':b.name,'left_sha256':digest(a),'right_sha256':digest(b),
                  'bc5_observation':'NOT_MEASURED','rust_parity':'NOT_VERIFIED'})

add('mp3_01_unchanged','mp3','Mesma origem, tags idênticas',lambda a,b:(mp3_set(a,[TIT2(encoding=3,text=['Equal'])]),mp3_set(b,[TIT2(encoding=3,text=['Equal'])])),'control')
add('mp3_02_id3v1','mp3','ID3v1 somente: título diferente',lambda a,b:(mp3_clear(a),mp3_clear(b),id3v1(a,'Esquerda'),id3v1(b,'Direita')),'id3v1')
add('mp3_03_id3v22','mp3','ID3v2.2: frame TT2 diferente',lambda a,b:(v22(a,'Original'),v22(b,'Alterado')),'id3v22')
add('mp3_04_id3v23','mp3','ID3v2.3: título diferente',lambda a,b:(mp3_set(a,[TIT2(encoding=1,text=['Original'])],3),mp3_set(b,[TIT2(encoding=1,text=['Alterado'])],3)),'id3v23')
add('mp3_05_id3v24','mp3','ID3v2.4: título diferente',lambda a,b:(mp3_set(a,[TIT2(encoding=3,text=['Original'])]),mp3_set(b,[TIT2(encoding=3,text=['Alterado'])])),'id3v24')

def conflicting(a,b):
    mp3_set(a,[TIT2(encoding=1,text=['Nova'])],3);id3v1(a,'Antiga')
    mp3_set(b,[TIT2(encoding=1,text=['Nova'])],3);id3v1(b,'Nova')
add('mp3_06_conflicting_versions','mp3','ID3v2.3 idêntico e ID3v1 conflitante',conflicting,'collision')
add('mp3_07_year_vs_date','mp3','ID3 TYER vs TDRC sem confundir campos',lambda a,b:(mp3_set(a,[TYER(encoding=1,text=['2020'])],3),mp3_set(b,[TDRC(encoding=3,text=['2020'])],4)),'semantic_mapping')
add('mp3_08_unicode','mp3','Unicode acentuado em ID3v2.4',lambda a,b:(mp3_set(a,[TIT2(encoding=3,text=['AÇÃO'])]),mp3_set(b,[TIT2(encoding=3,text=['ACAO'])])),'unicode')
add('mp3_09_whitespace','mp3','Espaços antes/depois do título',lambda a,b:(mp3_set(a,[TIT2(encoding=3,text=[' Faixa '])]),mp3_set(b,[TIT2(encoding=3,text=['Faixa'])])),'normalization')
add('mp3_10_case','mp3','Maiúsculas/minúsculas no título',lambda a,b:(mp3_set(a,[TIT2(encoding=3,text=['Faixa'])]),mp3_set(b,[TIT2(encoding=3,text=['FAIXA'])])),'normalization')
add('mp3_11_custom','mp3','TXXX descrição personalizada',lambda a,b:(mp3_set(a,[TXXX(encoding=3,desc='CUSTOM',text=['x'])]),mp3_set(b,[TXXX(encoding=3,desc='CUSTOM',text=['y'])])),'custom')
add('mp3_12_picture','mp3','APIC: capas com bytes diferentes',lambda a,b:(mp3_set(a,[APIC(encoding=3,mime='image/png',type=3,desc='',data=PNG1)]),mp3_set(b,[APIC(encoding=3,mime='image/png',type=3,desc='',data=PNG2)])),'artwork')
def swap_frame_order(a,b):
    mp3_set(a,[TIT2(encoding=3,text=['X']),TPE1(encoding=3,text=['Y'])])
    shutil.copy2(a,b)
    data=b.read_bytes()
    assert data[:3]==b'ID3' and data[3]==4
    total=((data[6]&127)<<21)|((data[7]&127)<<14)|((data[8]&127)<<7)|(data[9]&127)
    end=10+total
    pos=10; frames=[]
    while pos+10<=end and data[pos:pos+4] != b'\x00'*4:
        size=((data[pos+4]&127)<<21)|((data[pos+5]&127)<<14)|((data[pos+6]&127)<<7)|(data[pos+7]&127)
        assert size>0 and pos+10+size<=end
        frames.append(data[pos:pos+10+size]);pos+=10+size
    assert len(frames)==2, [x[:4] for x in frames]
    mutated=data[:10]+b''.join(reversed(frames))+data[pos:]
    assert len(mutated)==len(data) and mutated != data
    b.write_bytes(mutated)
add('mp3_13_order','mp3','Mesmos campos ID3 em ordem diferente',swap_frame_order,'ordering')
add('mp3_14_comment','mp3','Comentários múltiplos com idiomas',lambda a,b:(mp3_set(a,[COMM(encoding=3,lang='eng',desc='memo',text=['EN']), COMM(encoding=3,lang='por',desc='nota',text=['PT'])]),mp3_set(b,[COMM(encoding=3,lang='eng',desc='memo',text=['EN'])])),'repeated')

add('flac_01_unchanged','flac','FLAC mesmo VORBIS_COMMENT',lambda a,b:(flac_set(a,{'TITLE':['Igual']}),flac_set(b,{'TITLE':['Igual']})),'control')
add('flac_02_title','flac','FLAC TITLE diferente',lambda a,b:(flac_set(a,{'TITLE':['Alfa']}),flac_set(b,{'TITLE':['Beta']})),'vorbis')
add('flac_03_multivalue','flac','FLAC dois ARTIST vs um ARTIST',lambda a,b:(flac_set(a,{'ARTIST':['Ana','Bia']}),flac_set(b,{'ARTIST':['Ana']})),'multiplicity')
add('flac_04_reorder','flac','FLAC mesmos ARTIST invertidos',lambda a,b:(flac_set(a,{'ARTIST':['Ana','Bia']}),flac_set(b,{'ARTIST':['Bia','Ana']})),'ordering')
add('flac_05_duplicate','flac','FLAC valores ARTIST repetidos idênticos',lambda a,b:(flac_set(a,{'ARTIST':['Ana','Ana']}),flac_set(b,{'ARTIST':['Ana']})),'multiplicity')
add('flac_06_custom','flac','FLAC chave personalizada',lambda a,b:(flac_set(a,{'SOME_FIELD':['X']}),flac_set(b,{'SOME_FIELD':['Y']})),'custom')
add('flac_07_unicode','flac','FLAC Unicode decomposição vs pré-composição',lambda a,b:(flac_set(a,{'TITLE':['AÇÃO']}),flac_set(b,{'TITLE':['AC\u0327A\u0303O']})),'unicode')

def flac_pic(a,b):
    for p,data in [(a,PNG1),(b,PNG2)]:
        f=FLAC(p);f.clear();f['TITLE']=['Mesma faixa']
        pic=Picture();pic.type=3;pic.mime='image/png';pic.data=data
        f.add_picture(pic);f.save()
add('flac_08_picture','flac','FLAC PICTURE bytes diferentes',flac_pic,'artwork')

add('m4a_01_unchanged','m4a','MP4 ilst com título idêntico',lambda a,b:(mp4_set(a,{'\xa9nam':['Igual']}),mp4_set(b,{'\xa9nam':['Igual']})),'control')
add('m4a_02_title','m4a','MP4 atom ©nam diferente',lambda a,b:(mp4_set(a,{'\xa9nam':['Alfa']}),mp4_set(b,{'\xa9nam':['Beta']})),'mp4')
add('m4a_03_track','m4a','MP4 atom trkn difere',lambda a,b:(mp4_set(a,{'trkn':[(1,10)]}),mp4_set(b,{'trkn':[(2,10)]})),'numeric')
add('m4a_04_disc','m4a','MP4 atom disk difere',lambda a,b:(mp4_set(a,{'disk':[(1,2)]}),mp4_set(b,{'disk':[(1,3)]})),'numeric')
add('m4a_05_album_artist','m4a','MP4 album artist aART',lambda a,b:(mp4_set(a,{'aART':['Various']}),mp4_set(b,{'aART':['Another']})),'mapping')
add('m4a_06_freeform','m4a','MP4 freeform atom custom',lambda a,b:(mp4_set(a,{'----:com.apple.iTunes:TEST':[MP4FreeForm(b'One')]}),mp4_set(b,{'----:com.apple.iTunes:TEST':[MP4FreeForm(b'Two')]})),'freeform')
add('m4a_07_missing','m4a','MP4 tag presente só à esquerda',lambda a,b:(mp4_set(a,{'\xa9nam':['Alfa']}),mp4_set(b,{})),'missing')

def mp4_pic(a,b):
    mp4_set(a,{'covr':[MP4Cover(PNG1,imageformat=MP4Cover.FORMAT_PNG)]})
    mp4_set(b,{'covr':[MP4Cover(PNG2,imageformat=MP4Cover.FORMAT_PNG)]})
add('m4a_08_picture','m4a','MP4 covr com capa diferente',mp4_pic,'artwork')

manifest={'target':'Beyond Compare 5.2.7.32913','not_yet_expected':'Nenhuma comparação BC5 foi executada. Casos servem como entradas A/B.', 'cases':CASES}
(ROOT/'casos_manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
print('Cases:',len(CASES),'files:',len(list(FILES.iterdir())))
